/* engine/direct_codes.js : entitlement provider 'codes' (DIRECT edition). The buyer types an activation code; the code carries a duration (days).
   * codes are stored only as salted SHA-256 hashes (Moody.codesData.h = { hash: days }, generated by tools/direct/gen_codes.js)
   * each code works ONCE PER DEVICE; a new code ADDS its days on top of the remaining time
   * state lives in localStorage (try/catch), fully offline. When time runs out the paid missions lock again; progress is never touched.
   HONEST LIMIT: this is a client-side check. Anyone who can read the page source/localStorage can bypass it, and a code can be passed on to another device.
   It is a "soft" gate that is fine for personal sales, not real DRM. */
(function () {
  'use strict';
  const M = window.Moody, B = M.billing, D = M.codesData || { k: '', h: {} }, DAY = 864e5, KEY = 'family_codes_v1';
  let mem = null;
  function sha256(str) {   // WebCrypto when available (https / localhost), small JS fallback otherwise (plain http on a LAN address)
    try { if (window.crypto && crypto.subtle) return crypto.subtle.digest('SHA-256', new TextEncoder().encode(str)).then(b => Array.from(new Uint8Array(b)).map(x => ('0' + x.toString(16)).slice(-2)).join('')); } catch (e) { }
    return Promise.resolve(sha256js(str));
  }
  function sha256js(s) {
    const K = [], rr = (v, n) => (v >>> n) | (v << (32 - n)); let p = 0; const isP = n => { for (let i = 2; i * i <= n; i++) if (n % i === 0) return false; return true; };
    const H = []; for (let n = 2; K.length < 64; n++) if (isP(n)) { if (H.length < 8) H.push((Math.pow(n, .5) % 1) * 4294967296 | 0); K.push((Math.pow(n, 1 / 3) % 1) * 4294967296 | 0); }
    const b = Array.from(unescape(encodeURIComponent(s)), c => c.charCodeAt(0)), l = b.length * 8; b.push(0x80); while (b.length % 64 !== 56) b.push(0);
    for (let i = 7; i >= 0; i--) b.push(i > 3 ? 0 : (l >>> (i * 8)) & 255);
    for (let o = 0; o < b.length; o += 64) {
      const w = []; for (let i = 0; i < 16; i++) w[i] = (b[o + 4 * i] << 24) | (b[o + 4 * i + 1] << 16) | (b[o + 4 * i + 2] << 8) | b[o + 4 * i + 3];
      for (let i = 16; i < 64; i++) { const s0 = rr(w[i - 15], 7) ^ rr(w[i - 15], 18) ^ (w[i - 15] >>> 3), s1 = rr(w[i - 2], 17) ^ rr(w[i - 2], 19) ^ (w[i - 2] >>> 10); w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0; }
      let [a, bb, c, d, e, f, g, h] = H;
      for (let i = 0; i < 64; i++) { const t1 = (h + (rr(e, 6) ^ rr(e, 11) ^ rr(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0, t2 = ((rr(a, 2) ^ rr(a, 13) ^ rr(a, 22)) + ((a & bb) ^ (a & c) ^ (bb & c))) | 0; h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = bb; bb = a; a = (t1 + t2) | 0; }
      H[0] = (H[0] + a) | 0; H[1] = (H[1] + bb) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0; H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
    }
    return H.map(v => ('00000000' + (v >>> 0).toString(16)).slice(-8)).join('');
  }
  function cs(r) { let a = 5381; const s = [r.exp, (r.used || []).join(','), D.k].join('|'); for (let i = 0; i < s.length; i++) a = ((a << 5) + a + s.charCodeAt(i)) | 0; return (a >>> 0).toString(36); }
  function load() {
    let raw = null; try { raw = localStorage.getItem(KEY); } catch (e) { }
    if (!raw) return mem;
    try { const r = JSON.parse(raw); if (r && r.c === cs(r)) return (mem = r); } catch (e) { }
    return mem;   // damaged/edited record: ignore it (the in-memory copy of this session, if any, is kept)
  }
  function store(r) { r.c = cs(r); mem = r; try { localStorage.setItem(KEY, JSON.stringify(r)); } catch (e) { } }
  const norm = c => String(c || '').replace(/[٠-٩]/g, d => String(d.charCodeAt(0) - 0x660)).toUpperCase().replace(/[^A-Z0-9]/g, '');
  let bad = 0, lockUntil = 0;
  const codes = {
    available: () => true, init: async () => { load(); },
    getProducts: async () => [], purchase: async () => ({ result: 'failure', error: 'codes_only' }),
    getEntitlement: async () => {
      const r = load(); if (!r || !r.exp) return { state: 'NONE' };
      return r.exp > Date.now() ? { state: 'ACTIVE', sku: 'codes', expiry: r.exp } : { state: 'EXPIRED', sku: 'codes', expiry: r.exp, reason: 'expired' };
    },
    daysLeft() { const r = load(); return r && r.exp > Date.now() ? Math.ceil((r.exp - Date.now()) / DAY) : 0; },
    expiry() { const r = load(); return r && r.exp || 0; },
    /* -> { ok, days, exp } | { ok:false, why:'empty'|'bad'|'used'|'wait', wait? } */
    async activate(code) {
      if (Date.now() < lockUntil) return { ok: false, why: 'wait', wait: Math.ceil((lockUntil - Date.now()) / 1000) };
      const n = norm(code); if (n.length < 8) return { ok: false, why: 'empty' };
      const h = await sha256('FM1|' + n), days = (D.h || {})[h];
      if (!days) { if (++bad >= 5) { bad = 0; lockUntil = Date.now() + 30000; } return { ok: false, why: 'bad' }; }
      const r = load() || { exp: 0, used: [] }; r.used = r.used || [];
      if (r.used.indexOf(h) >= 0) return { ok: false, why: 'used' };
      bad = 0; const base = Math.max(Date.now(), r.exp || 0);
      r.used.push(h); r.exp = base + days * DAY; store(r);
      return { ok: true, days, exp: r.exp };
    }
  };
  B.register('codes', codes);
})();
